 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    # Marker at each outer boundary emits a horizontal/vertical beam inward;
    # beam continues through occupied cells and turns those cells into marker color.
    for r, c in markers:
        if r == 0:
            for y in range(r, h):
                if grid[y][c] == 2:
                    out[y][c] = 1
        elif r == h - 1:
            for y in range(r, -1, -1):
                if grid[y][c] == 2:
                    out[y][c] = 1
        elif c == 0:
            for x in range(c, w):
                if grid[r][x] == 2:
                    out[r][x] = 1
        elif c == w - 1:
            for x in range(c, -1, -1):
                if grid[r][x] == 2:
                    out[r][x] = 1
    # A beam paints entire 2-colored objects it hits, not just the row/column.
    seen = set()
    for r, c in markers:
        if r == 0:
            ray = [(y, c) for y in range(r, h)]
        elif r == h - 1:
            ray = [(y, c) for y in range(r, -1, -1)]
        elif c == 0:
            ray = [(r, x) for x in range(c, w)]
        else:
            ray = [(r, x) for x in range(c, -1, -1)]
        for y, x in ray:
            if grid[y][x] == 2:
                stack = [(y, x)]
                while stack:
                    a, b = stack.pop()
                    if (a,b) in seen or not (0 <= a < h and 0 <= b < w) or grid[a][b] != 2:
                        continue
                    seen.add((a,b))
                    out[a][b] = 1
                    stack.extend(((a-1,b),(a+1,b),(a,b-1),(a,b+1)))
    return out
